import re

def parse(lines):
    blocks = []
    skip = []
    cols = None
    cur = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        if re.match(r'^\S+:\S+:\S+>', l):
            skip.append(i)
            continue
        if re.match(r'^id\s+name\s', l):
            cols = [(m.start(), m.group()) for m in re.finditer(r'\S+', l)]
            cur = {'name': 'vdisks', 'kind': 'table', 'lines': [i], 'records': []}
            blocks.append(cur)
            continue
        if cols is None:
            continue
        rec = {}
        for k in range(len(cols)):
            s, n = cols[k]
            if k + 1 < len(cols):
                v = l[s:cols[k + 1][0]]
            else:
                v = l[s:]
            rec[n] = v.strip()
        cur['records'].append(rec)
        cur['lines'].append(i)
    return {'blocks': blocks, 'skip': skip}
